      const cta = document.createElement("button");
      cta.type = "button";
      cta.className = "cpb-btn-primary";
      cta.textContent = cpbCopy("Create Project", "创建项目");
      cta.addEventListener("click", () => { cpbClosePopover(); cpbOpenModal({ mode: "create", trigger: cta }); });
      actions.append(cta);
