      editorStyle?.setProperty("--spectrum-hue", `hsl(${draftHsv.h} 100% 50%)`);
      editorStyle?.setProperty("--spectrum-x", `${draftHsv.s * 100}%`);
      editorStyle?.setProperty("--spectrum-y", `${(1 - draftHsv.v) * 100}%`);
